{
  "findings": [
    {
      "check_id": "CKV_AWS_135",
      "title": "Ensure that EC2 is not launched with an outdated or vulnerable AMI",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The AMI used is Ubuntu 14.04, which is an outdated and potentially vulnerable version."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure that EC2 instances are not publicly exposed",
      "resource": "aws_instance.ubuntu",
      "severity": "CRITICAL",
      "explanation": "One of the EC2 instances is associated with a public IP address."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_20_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n}",
  "fix_summary": "Updated the AMI to a newer version and removed public IP association from all instances."
}
